# Surah Yunus (chapter 10) — part 2: ayat 11-20 (IDs 1375-1384)
SURAH = 10

ENTRIES = {
1375: (
"اور — اگر — اللہ — لوگوں کو — برائی — اسی طرح جلدی دے — جس طرح — وہ — بھلائی — میں جلدی کرتے ہیں — تو — ان — کی مدت — ختم — کر دی جائے — پس — ہم — ان — لوگوں کو — جن — کے — ہمارے پیش آنے — کی امید — نہیں رکھتے — ان کے — سرکشی — میں — بھٹکتے — چھوڑ دیتے ہیں",
"""۱۔ اللہ — بھلائیوں میں — جتنی جلدی دیتا ہے — برائیوں میں اتنی — جلدی نہیں دیتا۔
۲۔ ’’وَلَوْ يُعَجِّلُ اللَّهُ لِلنَّاسِ الشَّرَّ اسْتِعْجَالَهُم بِالْخَيْرِ لَقُضِيَ إِلَيْهِمْ أَجَلُهُمْ فَنَذَرُ الَّذِينَ لَا يَرْجُونَ لِقَاءَنَا فِي طُغْيَانِهِمْ يَعْمَهُونَ‘‘ — اور — اگر — اللہ — لوگوں کو — برائی — اسی طرح جلدی دے — جس طرح — وہ — بھلائی — میں جلدی کرتے ہیں — تو — ان — کی مدت — ختم — کر دی جائے — پس — ہم — ان — لوگوں کو — جن — کے — ہمارے پیش آنے — کی امید — نہیں رکھتے — ان کے — سرکشی — میں — بھٹکتے — چھوڑ دیتے ہیں — یعنی اللہ — بھلائی کے لیے جلدی نہیں کرتا — اور برائی بھی — ڈھیل دیتا ہے — مگر — آخرت کی طرف — جاتا ہے۔
۳۔ عملی سبق: فوراً — حساب نہیں — بہتر؛ اللہ کی ڈھیل — دائمی نہیں — ہے۔"""
),
1376: (
"اور — جب — انسان کو — نقصان — پہنچتا ہے — تو — وہ — ہمیں پکارتا ہے — اپنے پہلو، بیٹھنے اور کھڑے ہونے کی حالت میں — پس — جب — ہم — اس — کا نقصان — دور کر دیتے ہیں — تو — وہ — اس طرح — گزر جاتا ہے — گویا — اس — نے — ہمیں — کبھی پکارا ہی نہیں تھا — اسی طرح — فضول خرچی کرنے والوں کے — عمل — ان — کے لیے — خوبصورت نظر آتے ہیں",
"""۱۔ انسان — تکلیف میں اللہ کو پکارتا ہے — پھر — فراغت میں بھول جاتا ہے۔
۲۔ ’’وَإِذَا مَسَّ الْإِنسَانَ الضُّرُّ دَعَانَا لِجَنبِهِ أَوْ قَاعِدًا أَوْ قَائِمًا فَلَمَّا كَشَفْنَا عَنْهُ ضُرَّهُ مَرَّ كَأَن لَّمْ يَدْعُنَا إِلَىٰ ضُرٍّ مَّسَّهُ كَذَٰلِكَ زُيِّنَ لِلْمُسْرِفِينَ مَا كَانُوا يَعْمَلُونَ‘‘ — اور — جب — انسان کو — نقصان — پہنچتا ہے — تو — وہ — ہمیں پکارتا ہے — اپنے پہلو، بیٹھنے اور کھڑے ہونے کی حالت میں — پس — جب — ہم — اس — کا نقصان — دور کر دیتے ہیں — تو — وہ — اس طرح — گزر جاتا ہے — گویا — اس — نے — ہمیں — کبھی پکارا ہی نہیں تھا — اسی طرح — فضول خرچی کرنے والوں کے — عمل — ان — کے لیے — خوبصورت نظر آتے ہیں — یعنی تکلیف میں — انسان — اللہ کو یاد کرتا ہے — مگر — فراغت میں — بھول جاتا ہے۔
۳۔ عملی سبق: حال — چین میں ہو — یا — تکلیف میں — اللہ کو یاد رکھو۔"""
),
1377: (
"اور — ہم — نے — تم — سے پہلے — بہت سی — امتوں کو — ہلاک کر دیا — جب — انہوں نے — ظلم کیا — اور — ان — کے پاس — ان — کے رسول — واضح نشانیاں — لے کر آئے — اور — وہ — ایمان لانے والے نہ تھے — اسی طرح — ہم — مجرموں کو — بدلہ — دیتے ہیں",
"""۱۔ گزشتہ اقوام — ہلاک ہوئیں — ظلم کی وجہ سے۔
۲۔ ’’وَلَقَدْ أَهْلَكْنَا الْقُرُونَ مِن قَبْلِكُمْ لَمَّا ظَلَمُوا وَجَاءَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ وَمَا كَانُوا لِيُؤْمِنُوا كَذَٰلِكَ نَجْزِي الْقَوْمَ الْمُجْرِمِينَ‘‘ — اور — ہم — نے — تم — سے پہلے — بہت سی — امتوں کو — ہلاک کر دیا — جب — انہوں نے — ظلم کیا — اور — ان — کے پاس — ان — کے رسول — واضح نشانیاں — لے کر آئے — اور — وہ — ایمان لانے والے نہ تھے — اسی طرح — ہم — مجرموں کو — بدلہ — دیتے ہیں — یعنی ظالموں کا انجام — ہمیشہ — ہلاکت ہوتی ہے؛ رسولؐ کی بات نہ ماننا — سبب ہے۔
۳۔ عملی سبق: ظلم — خود کو تباہ کرتا ہے؛ انصاف — اختیار کرو۔"""
),
1378: (
"پھر — ہم — نے — تمہیں — ان — کے بعد — زمین میں — خلیفے بنایا — تاکہ — ہم — دیکھیں — تم — کیسے — عمل کرتے ہو",
"""۱۔ انسان — زمین میں خلیفہ — آزمائش — کے لیے۔
۲۔ ’’ثُمَّ جَعَلْنَاكُمْ خَلَائِفَ فِي الْأَرْضِ مِن بَعْدِهِمْ لِنَنظُرَ كَيْفَ تَعْمَلُونَ‘‘ — پھر — ہم — نے — تمہیں — ان — کے بعد — زمین میں — خلیفے بنایا — تاکہ — ہم — دیکھیں — تم — کیسے — عمل کرتے ہو — یعنی اللہ — ہم کو — زمین کا وارث بنایا — یہ — ہماری آزمائش — ہے۔
۳۔ عملی سبق: جان — لو — کہ تم خلیفہ ہو — ذمہ داری — کے ساتھ۔"""
),
1379: (
"اور — جب — ہماری — واضح آیات — ان — پر تلاوت کی جاتی ہیں — تو — وہ — لوگ — جو — ہمارے پیش آنے — کی — امید نہیں رکھتے — کہتے ہیں — اس کے علاوہ — اور — قرآن — لاؤ — یا — اسے — بدل دو — کہدو — مجھے — اختیار نہیں — کہ — میں — اپنی طرف سے — اسے — بدل دوں — میں — صرف — اس — کی پیروی کرتا ہوں — جو — میری طرف — وحی کیا جاتا ہے — بے شک — میں ڈرتا ہوں — اگر — میں — اپنے رب کی نافرمانی کروں — تو — ایک — عظیم دن کے عذاب — کا",
"""۱۔ کفار — قرآن کو بدلنے کا مطالبہ کرتے ہیں۔
۲۔ ’’وَإِذَا تُتْلَىٰ عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ لَا يَرْجُونَ لِقَاءَنَا ائْتِ بِقُرْآنٍ غَيْرِ هَٰذَا أَوْ بَدِّلْهُ قُلْ مَّا يَكُونُ لِي أَنْ أُبَدِّلَهُ مِن تِلْقَاءِ نَفْسِي إِنْ أَتَّبِعُ إِلَّا مَا يُوحَىٰ إِلَيَّ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ‘‘ — اور — جب — ہماری — واضح آیات — ان — پر تلاوت کی جاتی ہیں — تو — وہ — لوگ — جو — ہمارے پیش آنے — کی — امید نہیں رکھتے — کہتے ہیں — اس کے علاوہ — اور — قرآن — لاؤ — یا — اسے — بدل دو — کہدو — مجھے — اختیار نہیں — کہ — میں — اپنی طرف سے — اسے — بدل دوں — میں — صرف — اس — کی پیروی کرتا ہوں — جو — میری طرف — وحی کیا جاتا ہے — بے شک — میں ڈرتا ہوں — اگر — میں — اپنے رب کی نافرمانی کروں — تو — ایک — عظیم دن کے عذاب — کا — یعنی نبیؐ — قرآن کو — کبھی اپنی طرف سے — بدل نہیں سکتے؛ وہ — صرف — وحی کی پیروی کرتے ہیں۔
۳۔ عملی سبق: قرآن — خدا کی طرف سے — ہے؛ کسی کو — اختیار نہیں کہ — اسے بدل دے۔"""
),
1380: (
"کہدو — اگر — اللہ — چاہتا — تو — میں — اسے تم پر نہیں پڑھتا — اور — نہ — وہ — تمہیں — اس کے بارے میں — مطلع کرتا — میں — تو — اس سے پہلے — تمہارے درمیان ایک عمر — گزار چکا — کیا — تم — نہیں سمجھتے",
"""۱۔ نبیؐ کی — پچھلی زندگی — سچائی کی گواہ۔
۲۔ ’’قُلْ لَّوْ شَاءَ اللَّهُ مَا تَلَوْتُهُ عَلَيْكُمْ وَلَا أَدْرَاكُم بِهِ فَقَدْ لَبِثْتُ فِيكُمْ عُمُرًا مِّن قَبْلِهِ أَفَلَا تَعْقِلُونَ‘‘ — کہدو — اگر — اللہ — چاہتا — تو — میں — اسے تم پر نہیں پڑھتا — اور — نہ — وہ — تمہیں — اس کے بارے میں — مطلع کرتا — میں — تو — اس سے پہلے — تمہارے درمیان ایک عمر — گزار چکا — کیا — تم — نہیں سمجھتے — یعنی میں — تمہارے درمیان — ایک عمر — گزاری — میری دیانت داری — سے فائدہ اٹھاؤ۔
۳۔ عملی سبق: نبیؐ کی — زندگی — آپؐ کی صداقت — کی دلیل ہے۔"""
),
1381: (
"اس — سے زیادہ — ظالم کون ہے — جس نے — اللہ پر — جھوٹ — گھڑا — یا — اس کی آیات کو جھٹلایا — بے شک — مجرم — کامیاب — نہیں — ہوتے",
"""۱۔ اللہ پر جھوٹ گھڑنا — سب سے بڑا ظلم۔
۲۔ ’’فَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِآيَاتِهِ إِنَّهُ لَا يُفْلِحُ الْمُجْرِمُونَ‘‘ — اس — سے زیادہ — ظالم کون ہے — جس نے — اللہ پر — جھوٹ — گھڑا — یا — اس کی آیات کو جھٹلایا — بے شک — مجرم — کامیاب — نہیں — ہوتے — یعنی اللہ پر جھوٹ گھڑنا — سب سے بڑا ظلم ہے — مجرم — کبھی کامیاب نہیں ہوتے۔
۳۔ عملی سبق: اللہ پر جھوٹ گھڑنا — ناقابلِ معافی جرم ہے۔"""
),
1382: (
"وہ اللہ کے سوا — ان چیزوں کی عبادت کرتے ہیں — جو — نہ — انہیں نقصان پہنچاتی ہیں — اور — نہ فائدہ دیتی ہیں — اور — کہتے ہیں — یہ — اللہ کے نزدیک — ہمارے سفارشی — ہیں — کہدو — کیا — تم — اللہ — کو — ایسی چیز — کے بارے میں — خبر دیتے ہو — جو — اس — کے — آسمانوں اور زمین میں — معلوم نہیں؟ — وہ — پاک ہے — اور — وہ — اس — سے بلند ہے — جو — وہ شرک کرتے ہیں",
"""۱۔ بتوں کی عبادت — بے فائدہ — اور اللہ کے خلاف — افترا۔
۲۔ ’’وَيَعْبُدُونَ مِن دُونِ اللَّهِ مَا لَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَيَقُولُونَ هَٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّهِ قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لَا يَعْلَمُ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ‘‘ — وہ اللہ کے سوا — ان چیزوں کی عبادت کرتے ہیں — جو — نہ — انہیں نقصان پہنچاتی ہیں — اور — نہ فائدہ دیتی ہیں — اور — کہتے ہیں — یہ — اللہ کے نزدیک — ہمارے سفارشی — ہیں — کہدو — کیا — تم — اللہ — کو — ایسی چیز — کے بارے میں — خبر دیتے ہو — جو — اس — کے — آسمانوں اور زمین میں — معلوم نہیں؟ — وہ — پاک ہے — اور — وہ — اس — سے بلند ہے — جو — وہ شرک کرتے ہیں — یعنی بتوں کی عبادت — بے فائدہ ہے — وہ — اللہ کے نزدیک — سفارشی نہیں ہو سکتے؛ شفاعت — صرف — اللہ کی اجازت سے — چلتی ہے۔
۳۔ عملی سبق: عبادت — صرف اللہ کی کرو؛ کسی اور کو نہیں۔"""
),
1383: (
"لوگ — صرف ایک امت تھے — پھر — اختلاف — کرنے لگے — اور — اگر — تم — سے پہلے — تمہارے رب — کی بات — نہ ہوئی ہوتی — تو — ان — میں — جو — وہ — اختلاف کرتے ہیں — اس — میں — فیصلہ — ہو جاتا",
"""۱۔ لوگ — ایک امت تھے — اختلاف بعد کی بات ہے۔
۲۔ ’’وَمَا كَانَ النَّاسُ إِلَّا أُمَّةً وَاحِدَۃً فَاخْتَلَفُوا وَلَوْلَا كَلِمَۃٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِيَ بَيْنَهُمْ فِيمَا فِيهِ يَخْتَلِفُونَ‘‘ — لوگ — صرف ایک امت تھے — پھر — اختلاف — کرنے لگے — اور — اگر — تم — سے پہلے — تمہارے رب — کی بات — نہ ہوئی ہوتی — تو — ان — میں — جو — وہ — اختلاف کرتے ہیں — اس — میں — فیصلہ — ہو جاتا — یعنی لوگوں میں اختلاف — ابتدائی — بات نہیں — بعد میں پیدا ہوئے — اور اللہ — فیصلہ — موخر کرتا ہے۔
۳۔ عملی سبق: اختلاف — انسان کے اپنے — کیے کی وجہ سے — ہے؛ عدل — اختیار کرو۔"""
),
1384: (
"اور — وہ — کہتے ہیں — اس پر — کوئی نشانی — اس کے رب — کی طرف سے — کیوں نہیں اتاری گئی — کہدو — غیب — صرف — اللہ کا — ہے — پس — انتظار کرو — بے شک — میں بھی تمہارے ساتھ — منتظر ہوں",
"""۱۔ نشانی — کا مطالبہ — کفار کا پرانا حیلہ۔
۲۔ ’’وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَۃٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا الْغَيْبُ لِلَّهِ فَانتَظِرُوا إِنِّي مَعَكُم مِّنَ الْمُنتَظِرِينَ‘‘ — اور — وہ — کہتے ہیں — اس پر — کوئی نشانی — اس کے رب — کی طرف سے — کیوں نہیں اتاری گئی — کہدو — غیب — صرف — اللہ کا — ہے — پس — انتظار کرو — بے شک — میں بھی تمہارے ساتھ — منتظر ہوں — یعنی غیب کا علم — صرف اللہ کا ہے؛ آپ — انتظار کریں — جیسے — ہم — انتظار کر رہے ہیں۔
۳۔ عملی سبق: غیب کا علم — اللہ کے سوا — کسی کو نہیں؛ ایمان لانے میں تاخیر — بے کار ہے۔"""
),
}
